const { chromium } = require('/Users/yuvalt/personal/visual-renderer/bench/versus-browser/tooling/node_modules/playwright');
const path = require('path');

const SIZES = [
  ['square', 1080, 1080],
  ['landscape', 1920, 1080],
  ['story', 1080, 1920],
];
const FILE = 'file://' + path.resolve(__dirname, 'card.html');

(async () => {
  const browser = await chromium.launch();
  for (const [name, w, h] of SIZES) {
    const page = await browser.newPage({ viewportSize: { width: w, height: h } });
    await page.goto(FILE);
    await page.evaluate(() => document.fonts.ready);
    await page.waitForTimeout(300);

    const r = await page.evaluate(() => {
      const sel = ['.brand', '.event', '.avatar', '.name', '.role', '.title', '.meta', '.btn', '.speaker', '.content', '.foot'];
      const boxes = {};
      for (const s of sel) {
        const el = document.querySelector(s);
        const b = el.getBoundingClientRect();
        boxes[s] = { x: +b.x.toFixed(1), y: +b.y.toFixed(1), w: +b.width.toFixed(1), h: +b.height.toFixed(1), r: +b.right.toFixed(1), b: +b.bottom.toFixed(1) };
      }
      // clipping (scroll overflow) check
      const clipped = [];
      document.querySelectorAll('*').forEach(el => {
        if (el.scrollWidth > el.clientWidth + 1 || el.scrollHeight > el.clientHeight + 1) {
          const cs = getComputedStyle(el);
          if (cs.overflow !== 'visible' || el === document.documentElement)
            clipped.push(el.className || el.tagName);
        }
      });
      // out-of-viewport check for text elems
      const W = innerWidth, H = innerHeight;
      const oob = [];
      sel.forEach(s => {
        const b = boxes[s];
        if (b.x < -0.5 || b.y < -0.5 || b.r > W + 0.5 || b.b > H + 0.5) oob.push(s + ' ' + JSON.stringify(b));
      });
      // pairwise overlap among leaf content boxes
      const leaves = ['.brand', '.avatar', '.name', '.role', '.title', '.meta', '.btn'];
      const over = [];
      for (let i = 0; i < leaves.length; i++) for (let j = i + 1; j < leaves.length; j++) {
        const a = boxes[leaves[i]], c = boxes[leaves[j]];
        const ox = Math.min(a.r, c.r) - Math.max(a.x, c.x);
        const oy = Math.min(a.b, c.b) - Math.max(a.y, c.y);
        if (ox > 1 && oy > 1) over.push(`${leaves[i]} x ${leaves[j]} (${ox.toFixed(0)}x${oy.toFixed(0)})`);
      }
      const av = boxes['.avatar'];
      return { boxes, clipped, oob, over, circle: Math.abs(av.w - av.h) < 0.5, W, H,
               titleLines: Math.round(boxes['.title'].h / parseFloat(getComputedStyle(document.querySelector('.title')).lineHeight)) };
    });

    console.log(`\n=== ${name} ${w}x${h} ===`);
    console.log('avatar circle:', r.circle, r.boxes['.avatar'].w + 'x' + r.boxes['.avatar'].h);
    console.log('title lines:', r.titleLines, 'box:', JSON.stringify(r.boxes['.title']));
    console.log('clipped:', r.clipped.length ? r.clipped : 'none');
    console.log('out-of-bounds:', r.oob.length ? r.oob : 'none');
    console.log('overlaps:', r.over.length ? r.over : 'none');
    const b = r.boxes;
    console.log('gaps: brand.b=' + b['.brand'].b, 'speaker.y=' + b['.speaker'].y, 'speaker.b=' + b['.speaker'].b,
                'title.y=' + b['.title'].y, 'title.b=' + b['.title'].b, 'foot.y=' + b['.foot'].y, 'foot.b=' + b['.foot'].b, '/ H=' + r.H);
    await page.close();
  }
  await browser.close();
})();

